def priority(task, state, m=3.0, c=1.0, g=2.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    # hard SLO guard with superlinear boost past c*est to minimize excess waiting
    if ratio >= c:
        return 1e6 + g * (ratio - c) / est
    # otherwise SPT with tenant tiering and mild aging
    return tier * (1.0 / est) * (1.0 + 0.1 * ratio)

def priority(task, state, c=1.0, g=2.0, m=3.0, a=0.2):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    if ratio >= c:
        return 1e6 + g * (ratio - c) / est + tier * a * ratio
    return tier * (1.0 / est) * (1.0 + a * ratio)

def priority(task, state, c=1.2, m=2.5, k=1.0, q=0.5, b=0.4):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    congested = state.queue_len > q * max(state.capacity, 1.0)
    if ratio >= c:
        return 1e6 + tier * (1.0 / est) * (1.0 + b * ratio)
    if congested:
        slack = max(0.0, task.due - est - state.now)
        return tier * (1.0 / est) * (1.0 + b * math.exp(-slack / max(state.mean_est, 1e-6)))
    return tier / est

def priority(task, state, c=1.5, m=3.0, k=1.0, b=0.5, e=0.1):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    slack = max(0.0, task.due - est - state.now)
    urgency = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    if ratio >= c:
        return 1e6 + tier * (urgency + b * ratio)
    return tier * (urgency + e * ratio)

