    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    ratio = wait / est
    slack = task.due - state.now - est
    mean_est = max(state.mean_est, 1e-6)
    base = task.weight / est * (1.0 + b * ratio)
    if ratio >= c:
        return guard + base
    # urgency grows as slack shrinks; negative slack (already late) gets extra boost
    if slack <= 0:
        return guard + base * (1.0 + k)
    return base * (1.0 + k * mean_est / (mean_est + slack))

