import math
def priority(task, state, b=1.0, guard=2.0, guard_boost=1e6, qthresh=0.5, m=2.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    # Queue pressure: fraction of capacity work waiting
    pressure = state.queue_work / max(state.capacity, 1e-6)
    # Under load, favor SPT more; under light load, favor aging
    if pressure >= qthresh:
        base = tier * task.weight / est
    else:
        base = tier * task.weight / est * (1 + b * wait / est)
    if ratio >= guard:
        return guard_boost + base
    return base * (1.0 + min(ratio, guard) / max(guard, 1e-6))

