    slack = task.due - est - state.now
    if slack < 0:
        lateness = -slack / est
        slack_term = slack_w * (1.0 + lateness)
    else:
        slack_term = slack_w / (1.0 + slack / est)
    t = tier if task.tenant == 'premium' else 1.0
    # type-specific preference: reduce/join tend to be on critical path
    if task.task_type == 'reduce':
        type_boost = type_w * 1.0
    elif task.task_type == 'join':
        type_boost = type_w * 0.5
    else:
        type_boost = 0.0
    return guard_boost + t * (spt_w / est + slack_term) + age_w * wait / est + type_boost

